build_program:
/bin/cat > qa_version.js <<'QA253_NODE'
const fs=require('node:fs'),http=require('node:http');
function snap(){return {version:process.version,marker:process.env.MESSAGE,nvmrc:fs.readFileSync('/opt/render/project/src/.nvmrc','utf8'),selector:process.env.NODE_VERSION};}
if(process.argv[2]==='--snapshot'){console.log(JSON.stringify(snap()));}else{const built=JSON.parse(fs.readFileSync('/opt/render/project/src/qa-built.json','utf8'));http.createServer((req,res)=>{res.setHeader('Content-Type','application/json');res.end(JSON.stringify({built,runtime:snap()}));}).listen(Number(process.env.PORT||3000),'0.0.0.0');}
QA253_NODE
/usr/local/bin/node qa_version.js --snapshot > qa-built.json
/bin/cat qa-built.json

